fn start_scan() -> Task<Message> {
    use futures::SinkExt;
    let (mut stream_tx, stream_rx) = futures::channel::mpsc::unbounded();
    let (tx, mut rx) = tokio::sync::mpsc::channel(1);
    Task::batch([
        Task::future(async move {
            let handler = tauri_plugin_blec::get_handler()
                .expect("Failed to get BLE handler");
            handler
                .discover(
                    Some(tx),
                    1000,
                    tauri_plugin_blec::models::ScanFilter::None,
                    false,
                )
                .await
                .expect("Failed to start BLE scan");
            Message::ScanStarted
        }),
        Task::future(async move {
            while let Some(devices) = rx.recv().await {
                {
                    ::std::io::_print(
                        format_args!("Received BLE devices: {0:?}\n", devices),
                    );
                };
                let device_names = devices
                    .into_iter()
                    .map(|d| d.name)
                    .collect::<Vec<_>>();
                stream_tx
                    .send(Message::UpdateDevices(device_names))
                    .await
                    .expect("Failed to send devices to stream");
            }
            stream_tx
                .send(Message::ScanFinished)
                .await
                .expect("Failed to send scan finished");
            Message::ScanFinished
        }),
        Task::stream(stream_rx),
    ])
}
impl IcedApp for Counter {
    type Message = Message;
    fn init_plugins(builder: tauri::Builder<tauri::Wry>) -> tauri::Builder<tauri::Wry> {
        builder.plugin(tauri_plugin_blec::init())
    }
    fn new() -> (Self, Task<Self::Message>) {
        (Self::default(), Task::none())
    }
    fn update(&mut self, message: Self::Message) -> Task<Self::Message> {
        match message {
            Message::Increment => self.value += 1,
            Message::Decrement => self.value -= 1,
            Message::StartScan => {
                return start_scan();
            }
            Message::ScanStarted => {
                self.scan_running = true;
            }
            Message::ScanFinished => {
                self.scan_running = false;
            }
            Message::UpdateDevices(devices) => {
                self.devices = devices;
            }
        }
        Task::none()
    }
    fn view(&self) -> Element<'_, Self::Message, Theme, Renderer> {
        let counter = ::iced_widget::Column::with_children([
                ::iced_widget::core::Element::from(
                    button("Increment").on_press(Message::Increment),
                ),
                ::iced_widget::core::Element::from(
                    text(
                            ::alloc::__export::must_use({
                                ::alloc::fmt::format(format_args!("Value: {0}", self.value))
                            }),
                        )
                        .size(30),
                ),
                ::iced_widget::core::Element::from(
                    button("Decrement").on_press(Message::Decrement),
                ),
            ])
            .padding(20)
            .spacing(10)
            .align_x(Alignment::Center);
        let ble_scan = {
            let start_stop_button = if self.scan_running {
                button("Scanning...")
                    .style(|_theme, _status| button::Style {
                        background: Some(Color::from_rgb(0.8, 0.2, 0.2).into()),
                        ..Default::default()
                    })
            } else {
                button("Start BLE Scan").on_press(Message::StartScan)
            };
            ::iced_widget::Column::with_children([
                    ::iced_widget::core::Element::from(start_stop_button),
                    ::iced_widget::core::Element::from(text("Devices:").size(30)),
                    ::iced_widget::core::Element::from(
                        column(self.devices.iter().map(|d| text(d).into())).spacing(5),
                    ),
                ])
                .spacing(10)
                .align_x(Alignment::Center)
        };
        let content = ::iced_widget::Column::with_children([
                ::iced_widget::core::Element::from(counter),
                ::iced_widget::core::Element::from(ble_scan),
            ])
            .padding(20)
            .spacing(40)
            .align_x(Alignment::Center);
        container(content)
            .center_x(Length::Fill)
            .center_y(Length::Fill)
            .width(Length::Fill)
            .height(Length::Fill)
            .style(|_theme| container::Style {
                background: Some(Color::from_rgb(0.1, 0.1, 0.15).into()),
                ..Default::default()
            })
            .into()
    }
}
fn stop_unwind<F: FnOnce() -> T, T>(f: F) -> T {
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(f)) {
        Ok(t) => t,
        Err(err) => {
            {
                ::std::io::_eprint(
                    format_args!(
                        "attempt to unwind out of `rust` with err: {0:?}\n",
                        err,
                    ),
                );
            };
            std::process::abort()
        }
    }
}
